public boolean subsetSum(int[] nums, int T) {
    return can(nums, nums.length - 1, T);
}

private boolean can(int[] nums, int i, int rem) {
    if (rem == 0) {
        return true;
    }
    if (i < 0) {
        return false;
    }
    boolean exclude = can(nums, i - 1, rem);
    boolean include = false;
    if (nums[i] <= rem) {
        include = can(nums, i - 1, rem - nums[i]);
    }
    return exclude || include;
}

