def subset_sum(self, nums: list[int], T: int) -> bool:
    def can(i: int, rem: int) -> bool:
        if rem == 0:
            return True
        if i < 0:
            return False
        exclude = can(i - 1, rem)
        include = False
        if nums[i] <= rem:
            include = can(i - 1, rem - nums[i])
        return exclude or include

    return can(len(nums) - 1, T)

