public boolean subsetSum(int[] nums, int T) {
    Boolean[][] memo = new Boolean[nums.length][T + 1];
    return can(nums, nums.length - 1, T, memo);
}

private boolean can(int[] nums, int i, int rem, Boolean[][] memo) {
    if (rem == 0) {
        return true;
    }
    if (i < 0) {
        return false;
    }
    if (memo[i][rem] != null) {
        return memo[i][rem];
    }
    boolean result = can(nums, i - 1, rem, memo);
    if (!result && nums[i] <= rem) {
        result = can(nums, i - 1, rem - nums[i], memo);
    }
    memo[i][rem] = result;
    return result;
}

