def subset_sum(self, nums: list[int], T: int) -> bool:
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def can(i: int, rem: int) -> bool:
        if rem == 0:
            return True
        if i < 0:
            return False
        if can(i - 1, rem):
            return True
        if nums[i] <= rem:
            return can(i - 1, rem - nums[i])
        return False

    return can(len(nums) - 1, T)

