public boolean subsetSum(int[] nums, int T) {
    boolean[] dp = new boolean[T + 1];
    dp[0] = true;
    for (int num : nums) {
        for (int s = T; s >= num; s--) {
            dp[s] = dp[s] || dp[s - num];
        }
    }
    return dp[T];
}

// Bitset variant: bit s of `bits` means 'sum s reachable'
public boolean subsetSumBitset(int[] nums, int T) {
    java.math.BigInteger bits = java.math.BigInteger.ONE; // bit 0 set
    for (int num : nums) {
        bits = bits.or(bits.shiftLeft(num));
    }
    return bits.testBit(T);
}

code.python:
def subset_sum(self, nums: list[int], T: int) -> bool:
    dp = [False] * (T + 1)
    dp[0] = True
    for num in nums:
        for s in range(T, num - 1, -1):
            dp[s] = dp[s] or dp[s - num]
    return dp[T]

# Bitset variant: bit s of `bits` means 'sum s reachable'
def subset_sum_bitset(self, nums: list[int], T: int) -> bool:
    bits = 1  # bit 0 set: empty subset sums to 0
    for num in nums:
        bits |= bits << num
    return (bits >> T) & 1 == 1

